    public Object parseTicker(Object ticker, Map<String, Object> market)
    {
        // markPrices
        //
        //     {
        //         "symbol": "BTCUSDT",
        //         "markPrice": "11793.63104563", // mark price
        //         "indexPrice": "11781.80495970", // index price
        //         "estimatedSettlePrice": "11781.16138815", // Estimated Settle Price, only useful in the last hour before the settlement starts
        //         "lastFundingRate": "0.00038246",  // This is the lastest estimated funding rate
        //         "nextFundingTime": 1597392000000,
        //         "interestRate": "0.00010000",
        //         "time": 1597370495002
        //     }
        //
        // spot - ticker
        //
        //    {
        //        "symbol": "BTCUSDT",
        //        "priceChange": "-188.18000000",
        //        "priceChangePercent": "-0.159",
        //        "weightedAvgPrice": "118356.64734074",
        //        "lastPrice": "118449.03000000",
        //        "prevClosePrice": "118637.22000000",    // field absent in rolling ticker
        //        "lastQty": "0.00731000",                // field absent in rolling ticker
        //        "bidPrice": "118449.02000000",          // field absent in rolling ticker
        //        "bidQty": "7.15931000",                 // field absent in rolling ticker
        //        "askPrice": "118449.03000000",          // field absent in rolling ticker
        //        "askQty": "0.09592000",                 // field absent in rolling ticker
        //        "openPrice": "118637.21000000",
        //        "highPrice": "119273.36000000",
        //        "lowPrice": "117427.50000000",
        //        "volume": "14741.41491000",
        //        "quoteVolume": "1744744445.80640740",
        //        "openTime": "1753701474013",
        //        "closeTime": "1753787874013",
        //        "firstId": "5116031635",
        //        "lastId": "5117964946",
        //        "count": "1933312"
        //    }
        //
        // usdm tickers
        //
        //    {
        //        "symbol": "SUSDT",
        //        "priceChange": "-0.0229000",
        //        "priceChangePercent": "-6.777",
        //        "weightedAvgPrice": "0.3210035",
        //        "lastPrice": "0.3150000",
        //        "lastQty": "16",
        //        "openPrice": "0.3379000",
        //        "highPrice": "0.3411000",
        //        "lowPrice": "0.3071000",
        //        "volume": "120588225",
        //        "quoteVolume": "38709237.2289000",
        //        "openTime": "1753701720000",
        //        "closeTime": "1753788172414",
        //        "firstId": "72234973",
        //        "lastId": "72423677",
        //        "count": "188700"
        //    }
        //
        // coinm
        //
        //     {
        //         "baseVolume": "214549.95171161",
        //         "closeTime": "1621965286847",
        //         "count": "1283779",
        //         "firstId": "152560106",
        //         "highPrice": "39938.3",
        //         "lastId": "153843955",
        //         "lastPrice": "37993.4",
        //         "lastQty": "1",
        //         "lowPrice": "36457.2",
        //         "openPrice": "37783.4",
        //         "openTime": "1621878840000",
        //         "pair": "BTCUSD",
        //         "priceChange": "210.0",
        //         "priceChangePercent": "0.556",
        //         "symbol": "BTCUSD_PERP",
        //         "volume": "81990451",
        //         "weightedAvgPrice": "38215.08713747"
        //     }
        //
        // eapi: fetchTicker, fetchTickers
        //
        //     {
        //         "symbol": "ETH-230510-1825-C",
        //         "priceChange": "-5.1",
        //         "priceChangePercent": "-0.1854",
        //         "lastPrice": "22.4",
        //         "lastQty": "0",
        //         "open": "27.5",
        //         "high": "34.1",
        //         "low": "22.4",
        //         "volume": "6.83",
        //         "amount": "201.44",
        //         "bidPrice": "21.9",
        //         "askPrice": "22.4",
        //         "openTime": 1683614771898,
        //         "closeTime": 1683695017784,
        //         "firstTradeId": 12,
        //         "tradeCount": 22,
        //         "strikePrice": "1825",
        //         "exercisePrice": "1845.95341176"
        //     }
        //
        // spot bidsAsks
        //
        //     {
        //         "symbol":"ETHBTC",
        //         "bidPrice":"0.07466800",
        //         "bidQty":"5.31990000",
        //         "askPrice":"0.07466900",
        //         "askQty":"10.93540000"
        //     }
        //
        // usdm bidsAsks
        //
        //     {
        //         "symbol":"BTCUSDT",
        //         "bidPrice":"21321.90",
        //         "bidQty":"33.592",
        //         "askPrice":"21322.00",
        //         "askQty":"1.427",
        //         "time":"1673899207538"
        //     }
        //
        // coinm bidsAsks
        //
        //     {
        //         "symbol":"BTCUSD_PERP",
        //         "pair":"BTCUSD",
        //         "bidPrice":"21301.2",
        //         "bidQty":"188",
        //         "askPrice":"21301.3",
        //         "askQty":"10302",
        //         "time":"1673899278514"
        //     }
        //
        // fetchTicker: tokenized equities
        //
        //     {
        //         "symbol": "AAPL",
        //         "bidPrice": "339.51",
        //         "askPrice": "339.6",
        //         "bidSize": 45,
        //         "askSize": 90
        //     }
        //
        Long timestamp = (Long) this.safeInteger2(ticker, "closeTime", "time");
        String marketType = null;
        if ((((Map<?, ?>)ticker).containsKey("time")))
        {
            marketType = "contract";
        }
        if (java.util.Objects.equals(marketType, null))
        {
            marketType = (((((Map<?, ?>)ticker).containsKey("bidQty")))) ? "spot" : "contract";
        }
        String marketId = this.safeString(ticker, "symbol");
        String symbol = this.safeSymbol(marketId, market, null, marketType);
        String last = this.safeString(ticker, "lastPrice");
        String wAvg = this.safeString(ticker, "weightedAvgPrice");
        Boolean isCoinm = (((Map<?, ?>)ticker).containsKey("baseVolume"));
        String baseVolume = null;
        String quoteVolume = null;
        if (Boolean.TRUE.equals(isCoinm))
        {
            baseVolume = this.safeString(ticker, "baseVolume");
            // 'volume' field in inverse markets is not quoteVolume, but traded amount (per contracts)
            quoteVolume = Precise.stringMul(baseVolume, wAvg);
        } else
        {
            baseVolume = this.safeString(ticker, "volume");
            quoteVolume = this.safeString2(ticker, "quoteVolume", "amount");
        }
        final String finalBaseVolume = baseVolume;
        final String finalQuoteVolume = quoteVolume;
        return this.safeTicker(new HashMap<String, Object>() {{
            put( "symbol", symbol );
            put( "timestamp", timestamp );
            put( "datetime", Binance.this.iso8601(timestamp) );
            put( "high", Binance.this.safeString2(ticker, "highPrice", "high") );
            put( "low", Binance.this.safeString2(ticker, "lowPrice", "low") );
            put( "bid", Binance.this.safeString(ticker, "bidPrice") );
            put( "bidVolume", Binance.this.safeString2(ticker, "bidQty", "bidSize") );
            put( "ask", Binance.this.safeString(ticker, "askPrice") );
            put( "askVolume", Binance.this.safeString2(ticker, "askQty", "askSize") );
            put( "vwap", wAvg );
            put( "open", Binance.this.safeString2(ticker, "openPrice", "open") );
            put( "close", last );
            put( "last", last );
            put( "previousClose", Binance.this.safeString(ticker, "prevClosePrice") );
            put( "change", Binance.this.safeString(ticker, "priceChange") );
            put( "percentage", Binance.this.safeString(ticker, "priceChangePercent") );
            put( "average", null );
            put( "baseVolume", finalBaseVolume );
            put( "quoteVolume", finalQuoteVolume );
            put( "markPrice", Binance.this.safeString(ticker, "markPrice") );
            put( "indexPrice", Binance.this.safeString(ticker, "indexPrice") );
            put( "info", ticker );
        }}, market);
    }
    public Object parseTicker(Object ticker, Object... optionalArgs)
    {
        return this.parseTicker(ticker, Helpers.getArgMap(optionalArgs, 0, null));
    }

