    public String parseOrderStatus(String status)
    {
        Map<String, Object> statuses = new HashMap<String, Object>() {{
            put( "NEW", "open" );
            put( "PARTIALLY_FILLED", "open" );
            put( "ACCEPTED", "open" );
            put( "TRIGGERING", "open" );
            put( "FILLED", "closed" );
            put( "TRIGGERED", "closed" );
            put( "FINISHED", "closed" );
            put( "CANCELED", "canceled" );
            put( "CANCELLED", "canceled" );
            put( "PENDING_CANCEL", "canceling" );
            put( "REJECTED", "rejected" );
            put( "EXPIRED", "expired" );
            put( "EXPIRED_IN_MATCH", "expired" );
            put( "S", "ok" );
            put( "F", "rejected" );
        }};
        return this.safeString(statuses, status, status);
    }

    public String parseOrderTypeByMarket(String type, String marketType)
    {
        Map<String, Object> types = new HashMap<String, Object>() {{}};
        if ((!java.util.Objects.equals(marketType, null)) && java.util.Objects.equals(marketType, "spot"))
        {
            types = new HashMap<String, Object>() {{
                put( "limit_maker", "limit" );
                put( "stop_loss_limit", "limit" );
                put( "stop_loss", "market" );
                put( "take_profit_limit", "limit" );
                put( "take_profit", "market" );
            }};
        } else
        {
            types = new HashMap<String, Object>() {{
                put( "limit_maker", "limit" );
                put( "stop", "limit" );
                put( "stop_market", "market" );
                put( "take_profit", "limit" );
                put( "take_profit_market", "market" );
                put( "trailing_stop_market", "market" );
            }};
        }
        return this.safeString(types, ((String)type), type);
    }

