    public Object parseDepositAddress(Object response, Map<String, Object> currency)
    {
        //
        //     {
        //         "coin": "XRP",
        //         "address": "rEb8TK3gBgk5auZkwc6sHnwrGVJH8DuaLh",
        //         "tag": "108618262",
        //         "url": "https://bithomp.com/explorer/rEb8TK3gBgk5auZkwc6sHnwrGVJH8DuaLh"
        //     }
        //
        String url = this.safeString(response, "url");
        String address = this.safeString(response, "address");
        String currencyId = this.safeString(response, "currency");
        String code = this.safeCurrencyCode(currencyId, currency);
        // deposit-address endpoint provides only network url (not network ID/CODE)
        // so we should map the url to network (their data is inside currencies)
        Object networkCode = this.getNetworkCodeByNetworkUrl(code, url);
        String tag = this.safeString(response, "tag", "");
        if ((tag.length() == 0))
        {
            tag = null;
        }
        this.checkAddress(address);
        final String finalTag = tag;
        return new HashMap<String, Object>() {{
            put( "info", response );
            put( "currency", code );
            put( "network", networkCode );
            put( "address", address );
            put( "tag", finalTag );
        }};
    }
