    public Object parseLiquidation(Object liquidation, Map<String, Object> market)
    {
        //
        // margin
        //
        //     {
        //         "avgPrice": "0.00388359",
        //         "executedQty": "31.39000000",
        //         "orderId": 180015097,
        //         "price": "0.00388110",
        //         "qty": "31.39000000",
        //         "side": "SELL",
        //         "symbol": "BNBBTC",
        //         "timeInForce": "GTC",
        //         "isIsolated": true,
        //         "updatedTime": 1558941374745
        //     }
        //
        // linear
        //
        //     {
        //         "orderId": 6071832819,
        //         "symbol": "BTCUSDT",
        //         "status": "FILLED",
        //         "clientOrderId": "autoclose-1596107620040000020",
        //         "price": "10871.09",
        //         "avgPrice": "10913.21000",
        //         "origQty": "0.001",
        //         "executedQty": "0.002",
        //         "cumQuote": "10.91321",
        //         "timeInForce": "IOC",
        //         "type": "LIMIT",
        //         "reduceOnly": false,
        //         "closePosition": false,
        //         "side": "SELL",
        //         "positionSide": "BOTH",
        //         "stopPrice": "0",
        //         "workingType": "CONTRACT_PRICE",
        //         "origType": "LIMIT",
        //         "time": 1596107620044,
        //         "updateTime": 1596107620087
        //     }
        //
        // inverse
        //
        //     {
        //         "orderId": 165123080,
        //         "symbol": "BTCUSD_200925",
        //         "pair": "BTCUSD",
        //         "status": "FILLED",
        //         "clientOrderId": "autoclose-1596542005017000006",
        //         "price": "11326.9",
        //         "avgPrice": "11326.9",
        //         "origQty": "1",
        //         "executedQty": "1",
        //         "cumBase": "0.00882854",
        //         "timeInForce": "IOC",
        //         "type": "LIMIT",
        //         "reduceOnly": false,
        //         "closePosition": false,
        //         "side": "SELL",
        //         "positionSide": "BOTH",
        //         "stopPrice": "0",
        //         "workingType": "CONTRACT_PRICE",
        //         "priceProtect": false,
        //         "origType": "LIMIT",
        //         "time": 1596542005019,
        //         "updateTime": 1596542005050
        //     }
        //
        String marketId = this.safeString(liquidation, "symbol");
        Long timestamp = (Long) this.safeInteger2(liquidation, "updatedTime", "updateTime");
        return this.safeLiquidation((Map<String, Object>) (new HashMap<String, Object>() {{
            put( "info", liquidation );
            put( "symbol", Binance.this.safeSymbol(marketId, market) );
            put( "contracts", Binance.this.safeNumber(liquidation, "executedQty") );
            put( "contractSize", Binance.this.safeNumber(market, "contractSize") );
            put( "price", Binance.this.safeNumber(liquidation, "avgPrice") );
            put( "side", Binance.this.safeStringLower(liquidation, "side") );
            put( "baseValue", Binance.this.safeNumber(liquidation, "cumBase") );
            put( "quoteValue", Binance.this.safeNumber(liquidation, "cumQuote") );
            put( "timestamp", timestamp );
            put( "datetime", Binance.this.iso8601(timestamp) );
        }}));
    }
