    public Object parseConversion(Map<String, Object> conversion, Map<String, Object> fromCurrency, Map<String, Object> toCurrency)
    {
        //
        // fetchConvertQuote
        //
        //     {
        //         "quoteId":"12415572564",
        //         "ratio":"38163.7",
        //         "inverseRatio":"0.0000262",
        //         "validTimestamp":1623319461670,
        //         "toAmount":"3816.37",
        //         "fromAmount":"0.1"
        //     }
        //
        // createConvertTrade
        //
        //     {
        //         "orderId":"933256278426274426",
        //         "createTime":1623381330472,
        //         "orderStatus":"PROCESS"
        //     }
        //
        // createConvertTrade BUSD
        //
        //     {
        //         "tranId": 118263407119,
        //         "status": "S"
        //     }
        //
        // fetchConvertTrade, fetchConvertTradeHistory BUSD
        //
        //     {
        //         "tranId": 118263615991,
        //         "type": 244,
        //         "time": 1664442078000,
        //         "deductedAsset": "BUSD",
        //         "deductedAmount": "1",
        //         "targetAsset": "USDC",
        //         "targetAmount": "1",
        //         "status": "S",
        //         "accountType": "MAIN"
        //     }
        //
        // fetchConvertTrade
        //
        //     {
        //         "orderId":933256278426274426,
        //         "orderStatus":"SUCCESS",
        //         "fromAsset":"BTC",
        //         "fromAmount":"0.00054414",
        //         "toAsset":"USDT",
        //         "toAmount":"20",
        //         "ratio":"36755",
        //         "inverseRatio":"0.00002721",
        //         "createTime":1623381330472
        //     }
        //
        // fetchConvertTradeHistory
        //
        //     {
        //         "quoteId": "f3b91c525b2644c7bc1e1cd31b6e1aa6",
        //         "orderId": 940708407462087195,
        //         "orderStatus": "SUCCESS",
        //         "fromAsset": "USDT",
        //         "fromAmount": "20",
        //         "toAsset": "BNB",
        //         "toAmount": "0.06154036",
        //         "ratio": "0.00307702",
        //         "inverseRatio": "324.99",
        //         "createTime": 1624248872184
        //     }
        //
        Long timestamp = this.safeIntegerN(conversion, new ArrayList<Object>(Arrays.asList("time", "validTimestamp", "createTime")));
        String fromCur = this.safeString2(conversion, "deductedAsset", "fromAsset");
        String fromCode = this.safeCurrencyCode(fromCur, fromCurrency);
        String to = this.safeString2(conversion, "targetAsset", "toAsset");
        String toCode = this.safeCurrencyCode(to, toCurrency);
        return new HashMap<String, Object>() {{
            put( "info", conversion );
            put( "timestamp", timestamp );
            put( "datetime", Binance.this.iso8601(timestamp) );
            put( "id", Binance.this.safeStringN(conversion, new ArrayList<Object>(Arrays.asList("tranId", "orderId", "quoteId"))) );
            put( "fromCurrency", fromCode );
            put( "fromAmount", Binance.this.safeNumber2(conversion, "deductedAmount", "fromAmount") );
            put( "toCurrency", toCode );
            put( "toAmount", Binance.this.safeNumber2(conversion, "targetAmount", "toAmount") );
            put( "price", null );
            put( "fee", null );
        }};
    }
    public Object parseConversion(Map<String, Object> conversion, Object... optionalArgs)
    {
        return this.parseConversion(conversion, Helpers.getArgMap(optionalArgs, 0, null), Helpers.getArgMap(optionalArgs, 1, null));
    }

